// These Monaco modules have no declarations. They are loaded only to warm the
// language modules; no exports from them are consumed by the application.
declare module "monaco-editor/languages/features/html/htmlMode" { export {} }
declare module "monaco-editor/languages/features/css/cssMode" { export {} }
declare module "monaco-editor/languages/definitions/html/html" { export {} }
declare module "monaco-editor/languages/definitions/css/css" { export {} }
